insert into public.leadership (id, slug, name, title, role_group, bio, photo_id, instagram, needs_review, sort_order, status) values
  ('f46c936d-3036-974d-d6ea-01866363c78b'::uuid, 'charles-mugisha', 'Rev. Dr. Charles Mugisha', 'Founding Pastor', 'pastor', 'Pastor Charles Buregeya Mugisha is a pastor, global missionary and educator, and the founder and president of Africa New Life Ministries, which he began with his wife Florence in 2001. Born to a Rwandan family living as refugees, he studied theology at Reformed Theological College in Kampala, earned a master''s degree at Multnomah University in Portland, Oregon, and a doctorate from Gordon Conwell Theological Seminary. He serves as lead pastor of New Life Bible Church in Kigali. Charles and Florence have raised five children.', null, 'https://www.instagram.com/charlesbmugisha/', false, 1, 'published'),
  ('2f0f2d30-170e-eb25-61d6-304542ea5af6'::uuid, 'florence-mugisha', 'Pastor Florence Mugisha', 'Founding Pastor', 'pastor', 'Pastor Florence Mugisha is a cofounder of Africa New Life Ministries and its Director of Women''s Ministry. Growing up a Rwandan refugee in Uganda, she met Charles in college and later earned a master''s degree from Multnomah University. She used her own savings to help sponsor the first children when Africa New Life began, and today she is a preacher and motivational speaker with a heart for women and families.', null, 'https://www.instagram.com/florence.mugisha/', false, 2, 'published'),
  ('c7a0d1b5-e4b2-bbff-c7db-7e263242b119'::uuid, 'augustine-ndemezo', 'Augustine Ndemezo', 'Pastor', 'pastor', 'Augustine Ndemezo serves on the leadership team of New Life Global and has served with Africa New Life Ministries in Rwanda.', null, null, true, 3, 'published'),
  ('ad3459fb-f93a-fc4e-2e5d-4f82f9529b8c'::uuid, 'enock-rwakatale', 'Pastor Enock Rwakatale', 'Worship Pastor', 'pastor', 'Pastor Enock leads worship at New Life Global, including Refresh Women 2026 and the church''s 1st Anniversary celebration.', null, null, true, 4, 'published')
insert into public.ministries (id, slug, name, tagline, summary, description, image_id, meeting_schedule, location, contact_email, activities, join_url, sort_order, status) values
  ('aff7bfe5-e822-19e1-e3ce-7197b9e6d614'::uuid, 'worship', 'Worship', 'Lively, heartfelt worship', 'Leading the church into God''s presence on Sundays and at our Friday Night of Worship.', 'Worship sits at the heart of New Life. Our worship team leads the Sunday service and our Friday Night of Worship, where we spend unhurried time in praise and in the presence of God.', '4f45c193-e65f-85df-7678-1c6031def65a'::uuid, 'Sundays 3:00 PM · Fridays 8:00 PM', 'Chandler & Gilbert, AZ', null, array['Sunday worship','Night of Worship','Special services']::text[], '/contact?topic=worship', 1, 'published'),
  ('8b8212f7-6195-d9cd-b4aa-9e536621dab1'::uuid, 'prayer', 'Prayer', 'A praying church', 'Night Prayer every first Friday and Morning Glory prayer at 5 AM.', 'We take God''s Word and prayer seriously. On the first Friday of each month we gather for Night Prayer, and Morning Glory prayer meets at 5:00 AM every day except Monday and Saturday.', 'aa9b5df7-bbd7-db75-9eb3-e28d2863ba7d'::uuid, 'First Friday 9:00 PM · Morning Glory 5:00 AM', '800 W Galveston St, Chandler', null, array['Night Prayer','Morning Glory','Prayer requests']::text[], '/prayer', 2, 'published'),
  ('6a71e112-a519-2bd8-665f-e072a8333f0c'::uuid, 'women', 'Women', 'Refresh Women', 'Encouraging women to grow in faith together, and home of the Refresh Women conference.', 'Our women''s ministry gathers women of every age to laugh, worship, learn and grow together. In 2026 we hosted Refresh Women, a weekend of worship and teaching that left many refreshed and encouraged.', '23696574-257a-f9b8-b775-fed4212de455'::uuid, 'Announced through our events page', 'Chandler, AZ', null, array['Refresh Women conference','Fellowship','Bible teaching']::text[], '/contact?topic=women', 3, 'published'),
  ('6dea8b93-8947-887c-dd54-2055b285bd80'::uuid, 'children', 'Children', 'Sunday School', 'Our growing Sunday School shapes the next generation with God''s Word.', 'We believe our children are the next generation that will carry the Gospel to the nations. Sunday School meets during the Sunday service and is growing every week.', '445b1991-57f1-c6e4-6ab0-cced0a0d9314'::uuid, 'Sundays during the 3:00 PM service', '800 W Galveston St, Chandler', null, array['Sunday School','Bible stories','Worship for kids']::text[], '/visit#kids', 4, 'published'),
  ('7eaab1bc-57e7-6ac5-2b67-54acd7e208ce'::uuid, 'serve', 'Serve Team', 'Serving God and His people', 'Hospitality, ushering and practical care that make every Sunday feel like home.', 'Serving the Lord and His people is a gift we never take for granted. Our serve team welcomes guests, prepares the room and cares for our church family each week.', 'ec854e4c-208b-d8e2-ad23-2af3f253b242'::uuid, 'Sundays', '800 W Galveston St, Chandler', null, array['Welcome & hospitality','Ushering','Setup']::text[], '/contact?topic=serve', 5, 'published')
