insert into public.announcements (id, title, body, link_url, link_label, is_pinned, status) values
  ('9133cae1-ce43-79eb-5709-05a3731ab1f0'::uuid, 'Celebrate our 1st Anniversary, Dec 12 & 13', 'Join Pastors Charles & Florence Mugisha for worship and the Word.', '/events/first-anniversary-2026', 'Details', true, 'published')
insert into public.homepage_sections (key, kicker, title, body, data, sort_order, is_visible) values
  ('hero', null, null, null, '{"primaryCta":{"label":"Plan Your Visit","href":"/visit"},"secondaryCta":{"label":"Explore New Life","href":"#chapters"},"slides":[{"index":"01","label":"Faith & Worship","caption":"Worship, prayer and the Word","headline":"A place of love.\nA family of faith.","body":"We are a healthy church that transforms lives and nations through the Gospel of Jesus Christ and acts of compassion. Come worship with us every Sunday at 3:00 PM.","mediaId":"73543419-62b5-9629-b9c3-cd4826d929b4"},{"index":"02","label":"Community & Discipleship","caption":"Growing together as one family","headline":"Worship.\nGrow. Serve.","body":"From Sunday School to Refresh Women, we grow in Christ together and serve one another with joy.","mediaId":"bfbe240b-ad51-a269-40b6-c489cff6dd76"},{"index":"03","label":"Global Mission","caption":"From Rwanda to the nations","headline":"One family.\nTwo continents.","body":"Rooted in New Life Bible Church Kigali, founded by Pastors Charles and Florence Mugisha, and carrying love and hope to families and communities.","mediaId":"5ed08d2b-a57e-509d-bd9c-2d6a46e8139c"}]}'::jsonb, 1, true),
  ('stats', null, null, null, '{"items":[{"value":"3 PM","label":"Every Sunday in Chandler, AZ"},{"value":"2001","label":"Africa New Life founded in Rwanda"},{"value":"25","suffix":"yrs","label":"Of transforming lives"},{"value":"19,000","suffix":"+","label":"Students sponsored by Africa New Life"}]}'::jsonb, 2, true),
  ('chapters', 'Our Story', 'Three chapters. One story of new life.', 'New Life Global is a young church with deep roots. Here is who we are, in three chapters.', '{"chapters":[{"index":"01","title":"Faith & Worship","lead":"We worship God in a lively and heartfelt atmosphere.","body":"Every Sunday we gather to worship, to pray, and to hear the Bible taught in a way you can live. Our week is wrapped in prayer, from Morning Glory at 5 AM to Night Prayer on the first Friday of each month.","points":["Sunday Service · 3:00 PM","Night Prayer · first Friday","Night of Worship · Fridays"],"mediaId":"23696574-257a-f9b8-b775-fed4212de455","videoId":"8mEJiF-7SU8","cta":{"label":"Watch a message","href":"/messages"}},{"index":"02","title":"Community & Discipleship","lead":"Worship. Grow. Serve.","body":"We are a family of faith. Children grow in our Sunday School, women are refreshed and equipped, and everyone has a place to serve the Lord and His people.","points":["Sunday School","Refresh Women","Serve Team"],"mediaId":"719dd6cb-d89c-bcb6-d119-194ffd335ff2","cta":{"label":"Find your ministry","href":"/ministries"}},{"index":"03","title":"Global Mission","lead":"Go and make disciples of all nations.","body":"We share the vision of New Life Bible Church in Kigali, founded by Pastors Charles and Florence Mugisha: a healthy church that transforms lives and nations through the Gospel and acts of compassion. What began in Rwanda in 2001 has grown into churches, schools, a theological college and a hospital.","points":["Founded 2001 in Rwanda","New Life Bible Church, Kigali","Churches across Rwanda"],"mediaId":"5ed08d2b-a57e-509d-bd9c-2d6a46e8139c","cta":{"label":"Our Rwanda connection","href":"/about#rwanda"}}]}'::jsonb, 3, true),
  ('invite-band', 'Plan your visit', 'There''s a seat saved just for you.', 'Sundays at 3:00 PM · 800 W Galveston St, Chandler, AZ', '{"cta":{"label":"Plan Your Visit","href":"/visit"}}'::jsonb, 4, true),
  ('discover', 'Discover New Life', 'Find your way in.', 'Seven pathways into the life of our church.', '{"items":[{"title":"About Us","text":"Our story, beliefs and the Rwanda connection.","href":"/about"},{"title":"Ministries","text":"Worship, prayer, women, children and serving.","href":"/ministries"},{"title":"Messages","text":"Watch sermons from the New Life family.","href":"/messages"},{"title":"Events","text":"Gatherings, conferences and celebrations.","href":"/events"},{"title":"Leadership","text":"Meet our pastors.","href":"/about#leadership"},{"title":"Prayer","text":"Share a request in confidence.","href":"/prayer"},{"title":"Plan Your Visit","text":"Times, directions and what to expect.","href":"/visit"}]}'::jsonb, 5, true),
  ('pathways', 'Messages & Gatherings', 'Hear the Word. Gather with us.', 'Recent messages from the New Life family and what''s coming up in Chandler.', '{"messageMediaId":"59c733cc-f521-c709-34e0-0b8440356eec","eventMediaId":"ae4e1b59-837d-d18c-c8e2-41171ba911d1"}'::jsonb, 6, true),
  ('ministries', 'Ministries', 'A place for everyone to belong.', null, '{}'::jsonb, 7, true),
  ('global', 'One Family, Two Continents', 'Chandler and Kigali, joined in one mission.', 'New Life began in Rwanda in 2001 with Charles and Florence Mugisha, both raised as Rwandan refugees in Uganda. 25 years later, New Life Bible Churches, schools, the Africa College of Theology and Dream Medical Center serve communities across Rwanda. In Chandler, we carry that same Gospel and compassion.', '{"facts":[{"label":"2001","text":"Africa New Life begins in Kayonza, Rwanda"},{"label":"2003","text":"New Life Bible Church, Kigali is planted"},{"label":"2013","text":"Africa College of Theology opens"},{"label":"2018","text":"Dream Medical Center opens"},{"label":"2025","text":"New Life Global begins in Chandler, Arizona"}],"mediaId":"5ed08d2b-a57e-509d-bd9c-2d6a46e8139c","videoId":"9-581YAL-Ys","link":{"label":"Visit Africa New Life","href":"https://www.africanewlife.org/"}}'::jsonb, 8, true),
  ('testimonies', 'Stories', 'What God is doing among us.', null, '{"items":[],"note":"Only approved testimonies with written consent."}'::jsonb, 9, false),
  ('invitation', 'Come home', 'Come and experience new life.', 'Whoever you are and wherever you''re from, you are welcome at New Life Global.', '{"mediaId":"7bff3621-9295-6003-0f85-d78b9931ec27","cta":{"label":"Plan Your Visit","href":"/visit"},"secondary":{"label":"Contact us","href":"/contact"}}'::jsonb, 10, true)
